// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1 ether, uint256(1000 ether));
        // Adversarial callee that re-enters CashOut exactly once on the same amount.
        Reenterer attacker = new Reenterer(c, amount);

        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        bool ok; try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }
        assertTrue(ok, "deposit setup must succeed");

        // attacker now calls CashOut(amount); its receive() re-enters CashOut(amount) once.
        vm.prank(address(attacker));
        c.CashOut(amount);

        // On the reference, the balance was zeroed before the call, so the re-entrant
        // CashOut sees _am > balances[attacker] and makes no second transfer, leaving
        // the attacker with exactly 0 balance. On the buggy version the balance is still
        // `amount` during the re-entrancy, so a second transfer of `amount` succeeds
        // and the caller ends with (amount - amount) - amount underflowing / nonzero path.
        // We assert the caller's balance is strictly less than the amount (i.e., zero)
        // after the full CashOut returns.
        assertTrue(c.balances(address(attacker)) < amount, "reference must leave zero balance");
    }
}

contract Reenterer {
    PrivateBank private c;
    uint256 private amt;
    bool private entered;

    constructor(PrivateBank _c, uint256 _amt) {
        c = _c;
        amt = _amt;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            c.CashOut(amt);
        }
    }
}
